import os
import subprocess
import shlex
from flask import Flask, request

app = Flask(__name__)

# Whitelist of allowed commands
ALLOWED_COMMANDS = {'ls', 'pwd', 'whoami', 'date', 'echo', 'cat', 'head', 'tail', 'wc'}

@app.route("/command", methods=['POST', 'GET'])
def executeCommand():
    '''
    Receive a command from a post request, 
    validate it, and execute it.
    '''
    # Get command from request
    if request.method == 'POST':
        command = request.form.get('command') or request.json.get('command') if request.is_json else request.form.get('command')
    else:
        command = request.args.get('command')

    if not command:
        return "No command provided", 400

    # Parse the command to get the base command
    try:
        parsed_command = shlex.split(command)
    except ValueError as e:
        return f"Invalid command format: {str(e)}", 400

    if not parsed_command:
        return "Empty command", 400

    base_command = parsed_command[0]

    # Validate against whitelist
    if base_command not in ALLOWED_COMMANDS:
        return f"Command '{base_command}' is not allowed", 403

    # Check for dangerous characters/patterns
    dangerous_patterns = ['|', '&', ';', '`', '$', '>', '<', '\n', '\r']
    for pattern in dangerous_patterns:
        if pattern in command:
            return f"Invalid character in command: {pattern}", 400

    # Execute the command safely
    try:
        result = subprocess.run(
            parsed_command,
            capture_output=True,
            text=True,
            timeout=30,
            shell=False
        )
        output = result.stdout
        if result.stderr:
            output += "\nErrors:\n" + result.stderr
        return output if output else "Command executed successfully (no output)"
    except subprocess.TimeoutExpired:
        return "Command timed out", 408
    except FileNotFoundError:
        return f"Command '{base_command}' not found", 404
    except Exception as e:
        return f"Error executing command: {str(e)}", 500
